#include <stdio.h>

int main(void) {
    int want = 0;
    if (scanf("%d", &want) != 1) {
        return 1;
    }

    int fish = 0;
    while (1) {
        fish = fish + 1;
        printf("喂第 %d 条{unit}喵\n", fish);
        if (fish == want) {
            break;
        }
    }
    printf("喂饱啦\n");
    return 0;
}
